// WF-B / "Parse Command" — a Telegram uzenet ertelmezese.

const msg = $json.message || $json.edited_message || {};
const text = String(msg.text || '').trim();
const chatId = msg.chat ? msg.chat.id : null;

// Biztonsag: ha a TELEGRAM_CHAT_ID be van allitva, csak arrol a chatrol
// fogadunk parancsot. Enelkul barki, aki megtalalja a botot, hasznalhatna.
const allowed = $env.TELEGRAM_CHAT_ID;
if (allowed && String(chatId) !== String(allowed).trim()) {
  return [{ json: { command: 'ignore', chat_id: chatId, ignored: true } }];
}

const out = { chat_id: chatId, raw: text };

if (!text.startsWith('/')) {
  return [{ json: { ...out, command: 'help' } }];
}

const parts = text.slice(1).split(/\s+/);
const cmd = parts[0].toLowerCase().split('@')[0];   // /parancs@botnev kezelese

if (cmd === 'help' || cmd === 'start') {
  return [{ json: { ...out, command: 'help' } }];
}
if (cmd === 'slate' || cmd === 'kinalat' || cmd === 'kinálat') {
  return [{ json: { ...out, command: 'slate' } }];
}
const SLIP_CMDS = ['szelveny', 'szelvény', 'slip'];
if (!SLIP_CMDS.includes(cmd)) {
  return [{ json: { ...out, error: `Ismeretlen parancs: /${cmd}` } }];
}

// /szelveny <cel> [max<N>] [min<odds>]
const targetRaw = parts[1];
if (targetRaw === undefined) {
  return [{ json: { ...out, error: 'Add meg a cel-osszoddsot, pl. /szelveny 10' } }];
}
const target = Number(String(targetRaw).replace(',', '.'));
if (!Number.isFinite(target) || target <= 1) {
  return [{ json: { ...out, error: `Ervenytelen cel: "${targetRaw}". Szam kell, 1-nel nagyobb.` } }];
}
if (target > 10000) {
  return [{ json: { ...out, error: 'A cel tul nagy. 10000x alatt maradj.' } }];
}

let maxLegs = 4, minLegOdds = 1.30;
for (const p of parts.slice(2)) {
  const mMax = /^max(\d+)$/i.exec(p);
  if (mMax) { maxLegs = Math.max(1, Math.min(8, Number(mMax[1]))); continue; }
  const mMin = /^min([\d.,]+)$/i.exec(p);
  if (mMin) {
    const v = Number(mMin[1].replace(',', '.'));
    if (Number.isFinite(v) && v >= 1) minLegOdds = v;
    continue;
  }
}

return [{ json: { ...out, command: 'szelveny', target, maxLegs, minLegOdds } }];

// WF-B / "Build Response" — parancs -> szelveny.
// A szelvenyepito algoritmus lokalisan tesztelve lett, mielott ide kerult.

// ---------- szelvenyepito ----------
function buildSlip(pool, opts) {
  const T = opts.target;
  const maxLegs = opts.maxLegs || 4;
  const minLegOdds = opts.minLegOdds || 1.30;
  const tol = opts.tolerance || 0.12;
  const POOL_CAP = opts.poolCap || 40;

  let cand = pool.filter(l =>
    l.news_flag !== 'veto' &&
    l.confidence !== 'ALACSONY' &&
    l.tippmix_odds >= minLegOdds &&
    l.model_prob > 0
  );
  if (!cand.length) return { ok: false, reason: 'no_candidates' };

  // Minoseg = modell-valoszinuseg + bizalmi bonusz. NEM a modell-piac elteres:
  // meres szerint az elteresre szurni hibat szur, nem tudast.
  const confBonus = c => (c === 'MAGAS' ? 0.06 : c === 'KOZEPES' ? 0.02 : 0);
  cand.forEach(l => { l._q = l.model_prob + confBonus(l.confidence) - (l.news_flag === 'warn' ? 0.03 : 0); });
  cand.sort((a, b) => b._q - a._q);

  // Retegzett vagas odds-savonkent. Tiszta minoseg szerinti vagas kiszorna az
  // osszes magas oddsu labat, es a nagy cel-oddsok elerhetetlenne valnanak.
  const BANDS = [[1.0, 1.6], [1.6, 2.2], [2.2, 3.2], [3.2, 5.0], [5.0, Infinity]];
  const perBand = Math.max(4, Math.ceil(POOL_CAP / BANDS.length));
  const picked = [];
  for (const b of BANDS) {
    picked.push(...cand.filter(l => l.tippmix_odds >= b[0] && l.tippmix_odds < b[1]).slice(0, perBand));
  }
  cand = picked.sort((a, b) => b._q - a._q);
  if (!cand.length) return { ok: false, reason: 'no_candidates' };

  const maxOdds = Math.max(...cand.map(l => l.tippmix_odds));
  const nMin = Math.max(1, Math.ceil(Math.log(T) / Math.log(maxOdds)));
  if (nMin > maxLegs) return { ok: false, reason: 'target_too_high', nMin, maxLegs, maxOdds };

  const lo = T * (1 - tol), hi = T * (1 + tol);
  let best = null;

  // n novekvo sorrendben. Az ELSO n, amin van megoldas, nyer — mert a margo
  // labankent szorzodik: 2 lab ~86%-ot tart meg, 3 lab ~79%-ot, 6 lab ~63%-ot.
  for (let n = nMin; n <= maxLegs; n++) {
    const found = [];
    const dfs = (start, chosen, prod, used) => {
      if (found.length >= 400) return;
      if (chosen.length === n) {
        if (prod >= lo && prod <= hi) found.push({ legs: chosen.slice(), prod });
        return;
      }
      const remaining = n - chosen.length;
      for (let i = start; i < cand.length; i++) {
        if (cand.length - i < remaining) break;
        const l = cand[i];
        if (used.has(l.event_id)) continue;        // egy meccs = egy lab
        const p = prod * l.tippmix_odds;
        if (p * Math.pow(maxOdds, remaining - 1) < lo) continue;
        if (p > hi) continue;
        used.add(l.event_id); chosen.push(l);
        dfs(i + 1, chosen, p, used);
        chosen.pop(); used.delete(l.event_id);
      }
    };
    dfs(0, [], 1, new Set());
    if (found.length) {
      for (const f of found) {
        const jointP = f.legs.reduce((a, l) => a * l.model_prob, 1);
        const hiCount = f.legs.filter(l => l.confidence === 'MAGAS').length;
        const drift = Math.abs(f.prod - T) / T;
        f.score = jointP * (1 + 0.05 * hiCount) * (1 - drift);
        f.jointP = jointP;
      }
      found.sort((a, b) => b.score - a.score);
      best = found[0]; best.n = n;
      break;
    }
  }

  if (!best) {
    let closest = null;
    for (let n = nMin; n <= maxLegs; n++) {
      const greedy = []; const used = new Set(); let prod = 1;
      for (const l of cand) {
        if (greedy.length >= n) break;
        if (used.has(l.event_id)) continue;
        if (prod * l.tippmix_odds > hi && greedy.length) continue;
        greedy.push(l); used.add(l.event_id); prod *= l.tippmix_odds;
      }
      if (greedy.length === n) {
        const d = Math.abs(prod - T);
        if (!closest || d < closest.d) {
          closest = { legs: greedy, prod, n, d, jointP: greedy.reduce((a, l) => a * l.model_prob, 1) };
        }
      }
    }
    if (!closest) return { ok: false, reason: 'no_combination' };
    closest.ok = true; closest.approximate = true;
    return closest;
  }
  best.ok = true; best.approximate = false;
  return best;
}

// ---------- bemenet ----------
const cmd = (() => { try { return $('Parse Command').first().json; } catch (e) { return {}; } })();
const rows = $input.all().map(i => i.json).filter(r => r && r.leg_id);

const fmt = iso => {
  try {
    return new Date(iso).toLocaleString('hu-HU', { timeZone: 'Europe/Budapest',
      month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' });
  } catch (e) { return String(iso); }
};
const num = x => Number(x);

// csak a jovobeli meccsek
const now = Date.now();
const slate = rows.filter(r => {
  const t = new Date(r.kickoff).getTime();
  return Number.isFinite(t) && t > now + 10 * 60000;   // legalabb 10 perc mulva
}).map(r => ({
  ...r,
  model_prob: num(r.model_prob), market_prob: num(r.market_prob),
  tippmix_odds: num(r.tippmix_odds), market_avg_odds: num(r.market_avg_odds),
}));

const HELP = [
  '🎟 SZELVENYEPITO',
  '',
  '/szelveny 10        ~10x osszodds',
  '/szelveny 10 max3   legfeljebb 3 lab',
  '/szelveny 10 min2   labankent min 2.00 odds',
  '/slate              mai kinalat',
  '/help               ez a szoveg',
  '',
  'A rendszer a LEGKEVESEBB labbal eri el a celt, mert a',
  'margo labankent szorzodik: 2 labnal a fair ertek ~86%-a',
  'marad meg, 6 labnal mar csak ~63%-a.',
].join('\n');

let msg;

if (cmd.error) {
  msg = '❓ ' + cmd.error + '\n\n' + HELP;
} else if (cmd.command === 'help') {
  msg = HELP;
} else if (!slate.length) {
  msg = '📭 Ures a slate.\n\n'
      + (rows.length ? `${rows.length} sor van a tablaban, de mind mult ideju.\n` : 'Nincs sor a tablaban.\n')
      + 'A Slate Builder naponta 08:00-kor frissit. Futtasd le kezzel, ha most kell.';
} else if (cmd.command === 'slate') {
  const byMatch = {};
  slate.forEach(l => { (byMatch[l.match_name] = byMatch[l.match_name] || []).push(l); });
  const matches = Object.entries(byMatch)
    .sort((a, b) => new Date(a[1][0].kickoff) - new Date(b[1][0].kickoff))
    .slice(0, 15);
  const lines = matches.map(([m, ls]) => {
    const usable = ls.filter(l => l.confidence !== 'ALACSONY' && l.news_flag !== 'veto');
    const odds = usable.map(l => l.tippmix_odds).sort((a, b) => a - b);
    return `${m}\n   ${fmt(ls[0].kickoff)} · ${ls[0].league}\n   ${usable.length}/${ls.length} hasznalhato lab`
         + (odds.length ? `, odds ${odds[0].toFixed(2)}–${odds[odds.length - 1].toFixed(2)}` : '');
  });
  const usableTotal = slate.filter(l => l.confidence !== 'ALACSONY' && l.news_flag !== 'veto').length;
  const vetoed = slate.filter(l => l.news_flag === 'veto').length;
  msg = `📋 MAI KINALAT — ${matches.length} meccs\n\n${lines.join('\n\n')}\n\n──────────\n`
      + `${usableTotal} hasznalhato lab ${slate.length}-bol`
      + (vetoed ? `\n${vetoed} lab kizarva hir miatt` : '');
} else {
  // /szelveny
  const T = cmd.target;
  const r = buildSlip(slate, {
    target: T,
    maxLegs: cmd.maxLegs || 4,
    minLegOdds: cmd.minLegOdds || 1.30,
  });

  if (!r.ok) {
    const usable = slate.filter(l => l.confidence !== 'ALACSONY' && l.news_flag !== 'veto');
    if (r.reason === 'target_too_high') {
      msg = `⚠️ ${T}x nem erheto el ${r.maxLegs} labbal.\n\n`
          + `A legmagasabb elerheto odds most ${r.maxOdds.toFixed(2)}, ehhez `
          + `legalabb ${r.nMin} lab kellene.\n\n`
          + `Probald: /szelveny ${T} max${Math.min(8, r.nMin)}\n`
          + `De vedd figyelembe: ${r.nMin} labnal a fair ertek kb. `
          + `${(100 / Math.pow(1.08, r.nMin)).toFixed(0)}%-a marad meg.`;
    } else if (r.reason === 'no_candidates') {
      msg = `📭 Nincs hasznalhato lab.\n\n${slate.length} lab van a slate-en, de egyik sem felelt meg `
          + `a szuronek (min ${cmd.minLegOdds || 1.30} odds, nem ALACSONY bizalom, nincs hir-veto).\n\n`
          + `${usable.length} lab lenne hasznalhato alacsonyabb odds-kuszobbel.`;
    } else {
      msg = `⚠️ Nem talaltam kombinaciot ${T}x celra.\n\nProbalj mas celt vagy tobb labat: /szelveny ${T} max6`;
    }
  } else {
    const prod = r.legs.reduce((a, l) => a * l.tippmix_odds, 1);
    const jointP = r.legs.reduce((a, l) => a * l.model_prob, 1);
    const icon = { MAGAS: '🟢', KOZEPES: '🟡', ALACSONY: '🔴' };
    const blocks = r.legs.map((l, i) =>
      `${i + 1}. ${l.match_name}\n`
      + `   ${fmt(l.kickoff)} · ${l.league}\n`
      + `   ${l.label} @ ${l.tippmix_odds.toFixed(2)}\n`
      + `   modell ${(l.model_prob * 100).toFixed(0)}% · piac ${(l.market_prob * 100).toFixed(0)}% · `
      + `${icon[l.confidence] || ''} ${l.confidence === 'MAGAS' ? 'egyetert' : 'reszben egyetert'}`
      + (l.news_flag === 'warn' && l.news_note ? `\n   ⚠️ ${l.news_note}` : ''));

    const keep = 100 / Math.pow(1.08, r.n);
    msg = `🎟 SZELVENY — cel ${T}x\n\n${blocks.join('\n\n')}\n\n──────────\n`
        + `Osszodds (becsult): ${prod.toFixed(2)}x`
        + (r.approximate ? '  ⚠️ a cel pontosan nem volt elerheto' : '') + '\n'
        + `Bejovesi esely: ~${(jointP * 100).toFixed(1)}%  (kb. minden ${Math.round(1 / jointP)}. szelveny)\n`
        + `${r.n} lab — kevesebbel a cel nem erheto el\n\n`
        + `A Tippmixpro oddsok BECSULTEK (piaci atlag −4,5%).\n`
        + `Ellenorizd a valos oddsokat leadas elott.\n`
        + `Szelvenynel a margo labankent szorzodik: ${r.n} labnal\n`
        + `a fair ertek kb. ${keep.toFixed(0)}%-a marad meg.`;
  }
}

return [{ json: { message: msg, chat_id: cmd.chat_id, slate_rows: rows.length, future_rows: slate.length } }];
